 const healing=type==='heal'||type==='shield';
 fxNode(arena,`fx-number ${type}`,1150,{'--number-x':`${target==='hero'?27:73}%`,'--number-offset':`${(fxSerial++%3-1)*22}px`},`${healing?'+':type==='block'?'−':''}${Math.round(Number(value))}`);
