  fxNode(arena,`fx-projectile ${poison?'toxic':''}`,1000,{'--flight-y':`${42+(i-(count-1)/2)*(strong?7:5)}%`,'--flight-turn':`${(i-(count-1)/2)*3}deg`,'--delay':`${i*65}ms`});
